func mentionSearchURL(p model.Page) string {
	if p.Active == "detail" && p.Admin {
		return fmt.Sprintf("/admin/tickets/%d/mentions", p.Ticket.ID)
	}
	if p.Active == "detail" {
		return fmt.Sprintf("/tickets/mentions?except=%d", p.Ticket.ID)
	}
	return "/tickets/mentions"
}

